(function(){window.RoundedPieBridge={update:()=>{},data:()=>window.YunchengCharts?.slices||[],unit:()=>{const amount=document.querySelector('[data-measure="amount"]')?.classList.contains('selected');return amount?({total:'万元',annual:'万元/年',monthly:'万元/月'}[document.querySelector('#opportunity-basis')?.value]||'原始口径'):'个项目'},open:i=>document.querySelector('[data-legend-slice="'+i+'"]')?.click()};const previous=render;render=function(){previous();window.RoundedPieBridge.update()};document.body.classList.add('rounded-pie-preview')})();
